r13_v111_resident_piko_heard.source_text:
def r13_v111_resident_piko_heard(person):
    s=store.room13 or {}
    return (person in ("nabi","buri") and 3<=s.get("day",1)<=7
            and r13_v111_value("piko_alive") is False
            and "V111:E09" in s.get("evidence",[])
            and bool(r13_v111_value("piko_news3:"+person)))

r13_v111_required_business.source_text:
def r13_v111_required_business(person):
    # 재독 후속과 선택 자료 반응은 소식을 전할 일을 영구히 막는 필수 업무가 아니다.
    here=store.room13.get("location")
    return any(option.get("person")==person and option.get("location")==here
               for option in r13_v111_binding().get("options",[]))

r13_piko_required_business.source_text:
def r13_piko_required_business(person):
    # 선택 가능한 일상·의뢰 질문은 소식을 전할 일을 영구히 막지 않는다.
    return globals().get("r13_v111_required_business",r13_v111_has_business)(person)

r13_v111_followups.source_text:
def r13_v111_followups(person):
    # 이미 읽은 질문도 재독할 수 있지만, 죽었거나 자리를 떠난 사람을 다시 부르지는 않는다.
    if not r13_v111_person_alive(person) or r13_v111_value("departed:"+person):return []
    if not globals().get("r13_v111_actor_ready",lambda p:True)(person):return []
    return [spec for spec in R13_REACTIONS.get("followups",[])
            if spec["person"]==person and r13_v111_owned(spec["after"]) and r13_reaction_day_ok(spec)]

r13_v111_present_reaction.source_text:
def r13_v111_present_reaction(person,shown):
    """Lines for showing `shown` (a "V111:" record id) to `person`, or None."""
    key=shown[5:] if isinstance(shown,str) and shown.startswith("V111:") else shown
    for spec in R13_REACTIONS.get("present",[]):
        if spec["person"]==person and spec["evidence"]==key and r13_reaction_day_ok(spec):
            packets=r13_reaction_packets(spec["lines"])
            if packets:return packets
    generic=R13_REACTIONS.get("generic",{}).get(person) or []
    if generic:
        # Same evidence, same person -> same answer (stable, no random reroll on reload).
        row=generic[sum(ord(ch) for ch in str(key)) % len(generic)]
        return r13_reaction_packets([dict(speaker=next(n for n,p in MS14_SPEAKERS.items() if p==person),text=row["text"],expression=row.get("expression","neutral"))])
    return None
